constraints:
1 <= N <= 10^{5}
1 <= arr[i] <= 10^{5}

expected time complexity: O(N)
expected auxiliary space: O(N)

standard_solution_code:
class Solution:

	def nearestsmallRight(self, arr, n):
		st = [(arr[-1], n - 1)]
		ans = [(-1, i) for i in range(n)]
		ans[-1] = (-1, -1)
		for i in range(n - 2, -1, -1):
			if arr[i] <= st[-1][0]:
				while len(st) > 0 and arr[i] <= st[-1][0]:
					st.pop()
				if len(st) != 0:
					ans[i] = st[-1]
			else:
				ans[i] = st[-1]
			st.append((arr[i], i))
		return ans

	def nearestsmallLeft(self, arr, n):
		st = [(arr[0], 0)]
		ans = [(-1, i) for i in range(n)]
		ans[0] = (-1, -1)
		for i in range(1, n):
			if arr[i] <= st[-1][0]:
				while len(st) > 0 and arr[i] <= st[-1][0]:
					st.pop()
				if len(st) != 0:
					ans[i] = st[-1]
			else:
				ans[i] = st[-1]
			st.append((arr[i], i))
		return ans

	def nearestSmallestTower(self, arr):
		n = len(arr)
		ans = [-1 for i in range(n)]
		r = self.nearestsmallRight(arr, n)
		l = self.nearestsmallLeft(arr, n)
		for i in range(n):
			if r[i][0] == -1 and l[i][0] == -1:
				ans[i] = -1
			elif r[i][0] != -1 and l[i][0] != -1:
				if abs(i - r[i][1]) < abs(i - l[i][1]):
					ans[i] = r[i][1]
				elif abs(i - r[i][1]) > abs(i - l[i][1]):
					ans[i] = l[i][1]
				elif r[i][0] < l[i][0]:
					ans[i] = r[i][1]
				else:
					ans[i] = l[i][1]
			elif r[i][0] != -1:
				ans[i] = r[i][1]
			else:
				ans[i] = l[i][1]
		return ans
